const pipeline = (x) => x();

const importers = [
  async (path) => {
    if (!/^\.[\\/](?:packages\/familie-[^/]*?\/src(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.(mdx|stories\.(tsx)))$/.exec(path)) {
      return;
    }
  
    const pathRemainder = path.substring(11);
    return import(
      /* webpackChunkName: "[request]" */
      /* webpackInclude: /(?!.*node_modules)(?:\/packages\/familie-[^/]*?\/src(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.(mdx|stories\.(tsx)))$/ */
      './packages/' + pathRemainder
    );
  }
  ,
  async (path) => {
    if (!/^\.[\\/](?:packages\/familie-[^/]*?\/(?!\.)(?=.)[^/]*?\.(mdx|stories\.(tsx)))$/.exec(path)) {
      return;
    }
  
    const pathRemainder = path.substring(11);
    return import(
      /* webpackChunkName: "[request]" */
      /* webpackInclude: /(?!.*node_modules)(?:\/packages\/familie-[^/]*?\/(?!\.)(?=.)[^/]*?\.(mdx|stories\.(tsx)))$/ */
      './packages/' + pathRemainder
    );
  }
  
];

export async function importFn(path) {
  for (let i = 0; i < importers.length; i++) {
    const moduleExports = await pipeline(() => importers[i](path));
    if (moduleExports) {
      return moduleExports;
    }
  }
}